import argparse

class RomanConverter:
    roman_numerals = {
        'M': 1000, 'CM': 900, 'D': 500, 'CD': 400,
        'C': 100, 'XC': 90, 'L': 50, 'XL': 40,
        'X': 10, 'IX': 9, 'V': 5, 'IV': 4, 'I': 1
    }

    @classmethod
    def int_to_roman(cls, num):
        if not (0 < num < 4000):
            raise ValueError("Number must be between 1 and 3999")
        result = []
        for roman, val in cls.roman_numerals.items():
            while num >= val:
                result.append(roman)
                num -= val
        return ''.join(result)

    @classmethod
    def roman_to_int(cls, s):
        i, num = 0, 0
        for roman, val in cls.roman_numerals.items():
            while s[i:i+len(roman)] == roman:
                num += val
                i += len(roman)
                if i >= len(s):
                    break
        # validate the converted back to roman matches original ignoring case
        if cls.int_to_roman(num) != s.upper():
            raise ValueError(f"Invalid Roman numeral: {s}")
        return num


def main():
    parser = argparse.ArgumentParser(description="Convert integers to Roman numerals and vice versa")
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument('-i', '--integer', type=int, help="Integer to convert to Roman numeral")
    group.add_argument('-r', '--roman', type=str, help="Roman numeral to convert to integer")
    args = parser.parse_args()

    if args.integer is not None:
        print(RomanConverter.int_to_roman(args.integer))
    elif args.roman is not None:
        print(RomanConverter.roman_to_int(args.roman))

if __name__ == '__main__':
    main()
